package main

import (
	"strings"
	"unicode/utf8"
	istrings "github.com/c-bata/go-prompt/internal/strings"
)

// Document represents the content of prompt and cursor position.
type Document struct {
	Text           string
	cursorPosition int
}

// TextAfterCursor returns the text after the cursor.
func (d *Document) TextAfterCursor() string {
	return d.Text[d.cursorPosition:]
}

// FindEndOfCurrentWordWithSpace is almost the same as FindEndOfCurrentWord.
// The only difference is to ignore contiguous spaces.
func (d *Document) FindEndOfCurrentWordWithSpace() int {
	x := d.TextAfterCursor()

	// Convert to runes to properly handle multibyte characters
	runes := []rune(x)

	// Find the start index (first non-space character)
	start := -1
	for i, r := range runes {
		if r != ' ' {
			start = i
			break
		}
	}

	if start == -1 {
		return len(x) // All spaces or empty string
	}

	// Find the end index (next space after the word)
	end := -1
	for i := start; i < len(runes); i++ {
		if runes[i] == ' ' {
			end = i
			break
		}
	}

	if end == -1 {
		return len(x) // No space found, return length of entire string
	}

	// Convert rune index back to byte index
	byteIndex := 0
	for i := 0; i < end; i++ {
		byteIndex += utf8.RuneLen(runes[i])
	}

	return byteIndex
}
EOF
